import math


def count_binary_seq(n):
    """Write a function to find the count of all binary sequences of length 2n such that sum of first n bits is same as sum of last n bits."""
    # For a common sum k, the first half can be chosen in C(n, k) ways
    # and the second half independently in C(n, k) ways. Summing over k
    # gives sum_k C(n, k) ** 2, which by Vandermonde's identity equals
    # C(2n, n).
    return float(math.comb(2 * n, n))
